BEGIN;
CREATE TABLE IF NOT EXISTS organizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(180) NOT NULL, slug VARCHAR(100) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN ('pending','active','suspended')), logo_url TEXT, primary_color VARCHAR(20) NOT NULL DEFAULT '#315fce', secondary_color VARCHAR(20) NOT NULL DEFAULT '#14213a', branding JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organization_roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, role_key VARCHAR(80) NOT NULL, name VARCHAR(100) NOT NULL, description TEXT, permissions JSONB NOT NULL DEFAULT '[]'::jsonb, is_system BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,role_key), UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS organization_memberships (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, organization_role_id UUID NOT NULL REFERENCES organization_roles(id), status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN ('invited','active','suspended')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id));
CREATE TABLE IF NOT EXISTS platform_owners (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE recruitment_events ADD COLUMN IF NOT EXISTS organization_id UUID REFERENCES organizations(id);
INSERT INTO organizations(name,slug,status,branding) VALUES ('Legacy Workspace','legacy-workspace','active','{"registrationTitle":"Candidate registration","welcomeMessage":"Complete your details to apply.","footerText":"Powered by RecruitFlow"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
UPDATE recruitment_events SET organization_id=(SELECT id FROM organizations WHERE slug='legacy-workspace') WHERE organization_id IS NULL;
ALTER TABLE recruitment_events ALTER COLUMN organization_id SET NOT NULL;
CREATE INDEX IF NOT EXISTS idx_events_organization ON recruitment_events(organization_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_org_memberships_user ON organization_memberships(user_id,status);
CREATE INDEX IF NOT EXISTS idx_org_memberships_org ON organization_memberships(organization_id,status);
INSERT INTO platform_owners(user_id) SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='Super Admin' ON CONFLICT DO NOTHING;
INSERT INTO organization_roles(organization_id,role_key,name,description,permissions,is_system) SELECT o.id, lower(regexp_replace(r.name,'[^a-zA-Z0-9]+','_','g')), r.name, 'Migrated RecruitFlow role', '[]'::jsonb, true FROM organizations o CROSS JOIN roles r WHERE o.slug='legacy-workspace' AND r.name<>'Super Admin' ON CONFLICT (organization_id,role_key) DO NOTHING;
INSERT INTO organization_memberships(organization_id,user_id,organization_role_id,status) SELECT DISTINCT e.organization_id, eu.user_id, org_role.id, 'active' FROM event_users eu JOIN recruitment_events e ON e.id=eu.event_id JOIN roles global_role ON global_role.id=eu.assigned_role_id JOIN organization_roles org_role ON org_role.organization_id=e.organization_id AND org_role.role_key=lower(regexp_replace(global_role.name,'[^a-zA-Z0-9]+','_','g')) ON CONFLICT (organization_id,user_id) DO NOTHING;
COMMIT;